-- ============================================================
--  GAMIFICA — Biblioteca de Caça-palavras (Fundamental I)
--  40 jogos: 5 anos (1º a 5º) x 8 disciplinas, cada palavra com dica.
--  Idempotente: pode ser importado mais de uma vez sem duplicar.
--  Requer o professor demo (Ana Souza). Se não existir, ajuste o e-mail abaixo.
-- ============================================================
SET NAMES utf8mb4;

-- Professor e escola de referência (professor demo)
SET @prof := (SELECT id FROM usuarios WHERE email = 'ana@escola.edu.br' LIMIT 1);
SET @esc  := (SELECT escola_id FROM usuarios WHERE id = @prof LIMIT 1);

-- Turmas 1º a 5º Ano (cria se não existirem)

-- ═══════════════ 1º Ano ═══════════════
SET @turma := (SELECT id FROM turmas WHERE escola_id = @esc AND nome = '1º Ano' LIMIT 1);
SET @atv := (SELECT id FROM atividades WHERE turma_id=@turma AND titulo='➗ Caça-palavras de Matemática · 1º Ano' LIMIT 1);
SET @atv := (SELECT id FROM atividades WHERE turma_id=@turma AND titulo='📚 Caça-palavras de Português · 1º Ano' LIMIT 1);
SET @atv := (SELECT id FROM atividades WHERE turma_id=@turma AND titulo='🔤 Caça-palavras de Inglês · 1º Ano' LIMIT 1);
